from dataclasses import dataclass, asdict
from datetime import datetime

@dataclass
class Response:
    message: str
    timestamp: datetime
    status: int

def lambda_handler(event, context):
    response = Response(
        message='Success',
        timestamp=datetime.now(),
        status=200
    )
    # Good: converting to dict before returning
    return asdict(response)

